#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    int T;    cin >> T;     while(T--){        int n;        ll k, q;        cin >> n >> k >> q;         vector<ll> a(n);         for(int i = 0; i < n; i++){            cin >> a[i];        }         ll len = 0, ans = 0;         for(int j = 0; j < n; j++){            if(a[j] <= q){                len++;            }            else{                len = 0;            }             if(len >= k){                ans += (len - k + 1);            }        }         cout << ans << endl;    }}